Each block must contain one complete program. Do not provide any other text or markdown fences.

Here is the original GNU C++ code you have to rewrite:
<original_code>
#include <cstdio>
#include <cstring>
#include <iostream>
#include <algorithm>
using namespace std;
#define mod 1000000007
#define M 1000005
#define ll long long
ll p,k;
ll pow(ll a,ll b){
	ll res=1;
	ll x=a;
	while(b){
		if(b&1)res=(res*a)%mod;
		b>>=1;
		a=a*a%mod;
	}
	return res;
}
int main(){
	cin>>p>>k;
	if(k==0){
		cout<<pow(p,p-1)<<endl;
	}
	else if(k==1)cout<<pow(p,p)<<endl;
	else{
		ll sz=1;
		for(ll pos=k%p;pos!=1;++sz)pos=pos*k%p;
		ll cnt=(p-1)/sz;
		cout<<pow(p,cnt)<<endl;
	}
	return 0;
}

